using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Text;

namespace VoiceSubEditor
{
    /// <summary>内嵌 CP932 编码表(生成自 Python cp932), 免 NuGet 依赖的 Shift-JIS 读写与字节计数。</summary>
    public static class Cp932
    {
        const string EncB64 = @"";
        const string DecB64 = @"";

        static readonly Dictionary<int, ushort> Enc = new Dictionary<int, ushort>(10000);
        static readonly ushort[] Dec = new ushort[65536];
        static Cp932() { Init(); }

        static void Init()
        {
            try
            {
                byte[] encRaw = Decompress(Convert.FromBase64String(EncB64));
                for (int i = 0; i < encRaw.Length; i += 6)
                {
                    int uni = BitConverter.ToInt32(encRaw, i);
                    ushort word = BitConverter.ToUInt16(encRaw, i + 4);
                    if (!Enc.ContainsKey(uni)) Enc[uni] = word;
                }
                byte[] decRaw = Decompress(Convert.FromBase64String(DecB64));
                for (int w = 0; w < 65536; w++)
                    Dec[w] = BitConverter.ToUInt16(decRaw, w * 2);
            }
            catch { }
        }

        static byte[] Decompress(byte[] gz)
        {
            using (var ms = new MemoryStream(gz))
            using (var zip = new DeflateStream(ms, CompressionMode.Decompress))
            using (var outMs = new MemoryStream())
            {
                // NOTE: 数据为 raw deflate(无 zlib 头), 与 DeflateStream 匹配
                zip.CopyTo(outMs);
                return outMs.ToArray();
            }
        }

        /// <summary>能否编码全部字符</summary>
        public static bool CanEncode(string s)
        {
            if (s == null) return true;
            foreach (char c in s) if (!Enc.ContainsKey(c)) return false;
            return true;
        }

        /// <summary>取字符的 CP932 编码(单字节=字节值, 双字节=高位<<8|低位); 无编码返回 false</summary>
        public static bool TryGetWord(char c, out ushort word)
        {
            return Enc.TryGetValue(c, out word);
        }

        /// <summary>双字节码位(b1&lt;&lt;8|b2)按 CP932 解码; 无效返回 false</summary>
        public static bool TryDecodeWord(ushort word, out char c)
        {
            ushort uni = Dec[word];
            if (uni == 0) { c = '?'; return false; }
            c = (char)uni;
            return true;
        }

        /// <summary>CP932 字节数; 无法编码的字符按 2 字节计(自定义码表假定为双字节)并置 hasBad</summary>
        public static int ByteCount(string s, out bool hasBad)
        {
            hasBad = false;
            if (s == null) return 0;
            int n = 0;
            foreach (char c in s)
            {
                if (Enc.TryGetValue(c, out ushort w)) n += (w > 0xFF) ? 2 : 1;
                else { n += 2; hasBad = true; }
            }
            return n;
        }

        /// <summary>编码为 CP932 字节; 失败抛异常(列出坏字符)</summary>
        public static byte[] Encode(string s)
        {
            var ms = new MemoryStream();
            foreach (char c in s)
            {
                if (!Enc.TryGetValue(c, out ushort w))
                    throw new NotSupportedException("CP932 无法编码字符: " + c + " (U+" + ((int)c).ToString("X4") + ")");
                if (w > 0xFF) { ms.WriteByte((byte)(w >> 8)); ms.WriteByte((byte)(w & 0xFF)); }
                else ms.WriteByte((byte)w);
            }
            return ms.ToArray();
        }

        /// <summary>CP932 字节解码为字符串(未定义字节替换为 ?)</summary>
        public static string Decode(byte[] data)
        {
            var sb = new StringBuilder(data.Length);
            int i = 0;
            while (i < data.Length)
            {
                int b = data[i];
                ushort word;
                if (b >= 0x81 && b <= 0x9F || b >= 0xE0 && b <= 0xFC)
                {
                    if (i + 1 >= data.Length) { sb.Append("?"); break; }
                    word = (ushort)((b << 8) | data[i + 1]);
                    i += 2;
                }
                else { word = (ushort)b; i += 1; }
                ushort uni = Dec[word];
                sb.Append(uni != 0 ? (char)uni : "?");
            }
            return sb.ToString();
        }
    }
}
